s = input()
(arr, zero, one) = ([], [], [])
for i in range(len(s)):
	if s[i] == '0':
		if one:
			idx = one.pop()
			arr[idx].append(i + 1)
			zero.append(idx)
		else:
			zero.append(len(arr))
			arr.append([i + 1])
	else:
		if not zero:
			break
		idx = zero.pop()
		one.append(idx)
		arr[idx].append(i + 1)
if arr and zero and (not one):
	print(len(arr))
	for x in zero:
		print(len(arr[x]), end=' ')
		print(*arr[x])
else:
	print(-1)
